    @staticmethod
    def _require_object_body(body):
        if not isinstance(body, dict):
            raise InvalidRequestError("request body must be a JSON object")

    def _receipt_payload(self, row, *, project_id):
        """Expose the canonical receipt facts committed with the mutation."""
        if row is None or row["txn_id"] is None:
            return None
        active = self._active_task_admission_result(row)
        if active is not None:
            result = active
        else:
            result = self._publication_replay_result(row) if row["command_kind"] == "parent_composition.publish" else command_result(
                row["result_json"], kind=row["command_kind"], connection=self.store.conn,
                created_at=None if row["command_kind"] in {"object.ingest", "media.import", "timeline.commit"} else row["created_at"],
            )
        return {
            "receipt_id": row["txn_id"],
            "command_kind": row["command_kind"],
            "idempotency_key": row["idempotency_key"],
            "request_hash": row["request_hash"],
            "project_id": project_id,
            "project_seq": [int(row["first_project_seq"]), int(row["last_project_seq"])],
            "event_ids": json.loads(row["event_ids_json"]),
            "result": result,
            "created_at": row["created_at"],
        }

    def _active_task_admission_result(self, row):
        if row["command_kind"] != "task.create" or "primary_stream_id" not in row.keys() or not row["primary_stream_id"]:
            return None
        with self.store._mutex:
            run = self.store.conn.execute("SELECT * FROM runs WHERE id=?", (row["primary_stream_id"],)).fetchone()
            task = self.store.conn.execute("SELECT * FROM tasks WHERE run_id=?", (row["primary_stream_id"],)).fetchone()
            if run is None or task is None or task["status"] not in {"queued", "running", "cancel_requested"}:
                return None
            return self.store._task_result(run, task)

    def _publication_replay_result(self, row):
        """Rebuild the exact old response from immutable revision/event evidence."""
        stored = json.loads(row["result_json"])
        if IDEMPOTENCY_RESULT_MARKER not in stored:
            return stored
        project_id = stored["project_id"]
        timeline_id = stored["timeline_id"]
        revision_id = stored["parent_revision_id"]
        parent_row = self.store.conn.execute(
            "SELECT * FROM parent_composition_revisions WHERE id=? AND project_id=? AND timeline_id=?",
            (revision_id, project_id, timeline_id),
        ).fetchone()
        if parent_row is None:
            raise NotFoundError("compacted publication revision is missing")
        parent, shots, internal = load_closure(self.store.conn, project_id, timeline_id, parent_row)
        event_row = self.store.conn.execute(
            "SELECT * FROM timeline_events WHERE id=? AND timeline_id=? AND kind='parent.composition.published'",
            (stored["event_id"], timeline_id),
        ).fetchone()
        if event_row is None:
            raise ConflictError("compacted publication event is missing")
        event = json.loads(event_row["payload_json"])
        manifest = event["dependency_manifest"]
        if (event["project_id"] != project_id or event["new_head"] != revision_id
                or event["content_digest"] != parent_row["content_digest"]
                or hashlib.sha256(canonical_json(manifest).encode()).hexdigest() != stored["dependency_manifest_sha256"]):
            raise ConflictError("compacted publication evidence disagrees with revision")
        seam_report, _ = evaluate_closure(parent, shots, internal, timeline_id=timeline_id)
        digest = parent_row["content_digest"]
        result = {
            "project_id": project_id, "timeline_id": timeline_id,
            "revision_id": revision_id, "parent_revision_id": revision_id,
            "content_digest": digest, "payload": parent,
            "old_head": event["old_head"], "new_head": revision_id,
            "dependency_manifest": manifest,
            "content_digests": {"parent": digest,
                **{item["revision_id"]: item["content_digest"] for item in manifest["shots"] + manifest["internal_timelines"]},
                **{item["media_id"]: item["content_digest"] for item in manifest["media"]}},
            "event_id": stored["event_id"], "created_at": stored["created_at"],
            "visual_seam_report": seam_report,
        }
        if hashlib.sha256(canonical_json(result).encode()).hexdigest() != stored[IDEMPOTENCY_RESULT_MARKER]:
            raise ConflictError("compacted publication replay does not match original response")
        return result

    def committed_receipt(self, command_kind, aggregate_id, idempotency_key, *, project_id):
        """Return the receipt persisted with a successful mutation.

        This reads the command ledger; it never derives a receipt from client
        state or caches one in the service process.
        """
        if not idempotency_key:
            return None
        # HTTP handlers share the owner's SQLite connection. Serialize this
        # post-mutation read with the writer lock so another handler cannot
        # interleave a transaction on the same connection between the
        # mutation and receipt lookup, yielding a spurious null receipt.
        with self.store._mutex:
            row = self.store.conn.execute(
                "SELECT txn_id, command_kind, idempotency_key, request_hash, result_json, "
                "first_project_seq, last_project_seq, event_ids_json, created_at, primary_stream_id "
                "FROM command_idempotency WHERE command_kind=? AND aggregate_id=? AND idempotency_key=?",
                (command_kind, aggregate_id, idempotency_key),
            ).fetchone()
        return self._receipt_payload(row, project_id=project_id) if row else None

    def _command_replay_state(self, kind, aggregate_id, idempotency_key, request_hash, *, project_id=None, with_receipt=True):
        """Return ``(found, value)`` so a committed null result is replayable."""
        if idempotency_key is None:
            return False, None
        validate_idempotency_key(idempotency_key)
        if kind in {"task.claim", "executor.register"}:
            query = (
                "SELECT NULL AS txn_id, command_kind, idempotency_key, request_hash, result_json, "
                "NULL AS first_project_seq, NULL AS last_project_seq, NULL AS event_ids_json, created_at "
                "FROM session_command_replay WHERE command_kind=? AND aggregate_id=? AND idempotency_key=?"
            )
        else:
            query = (
                "SELECT txn_id, command_kind, idempotency_key, request_hash, result_json, "
                "first_project_seq, last_project_seq, event_ids_json, created_at "
                "FROM command_idempotency WHERE command_kind=? AND aggregate_id=? AND idempotency_key=?"
            )
        prior = self.store.conn.execute(query, (kind, aggregate_id, idempotency_key)).fetchone()
        if not prior:
            return False, None
        if prior["request_hash"] != request_hash:
            raise ConflictError("idempotency key was already used with different input")
        result = self._publication_replay_result(prior) if kind == "parent_composition.publish" else command_result(
            prior["result_json"], kind=kind, connection=self.store.conn,
            created_at=None if kind in {"object.ingest", "media.import", "timeline.commit"} else prior["created_at"],
            window_seconds=SESSION_IDEMPOTENCY_WINDOW_SECONDS if kind in {"task.claim", "executor.register"} else IDEMPOTENCY_RESULT_WINDOW_SECONDS,
        )
        if project_id is not None and with_receipt:
            result = {"data": result, "receipt": self._receipt_payload(prior, project_id=project_id)}
        return True, result

    def _command_replay(self, kind, aggregate_id, idempotency_key, request_hash, *, project_id=None, with_receipt=True):
        found, result = self._command_replay_state(
            kind, aggregate_id, idempotency_key, request_hash,
            project_id=project_id, with_receipt=with_receipt,
        )
        return result if found else None

    def _command_record(self, kind, aggregate_id, idempotency_key, request_hash, result, *, project_id=None, event_ids=(), primary_stream_id=None, resulting_stream_seq=None, with_receipt=True, created_at=None):
        if idempotency_key is not None:
            validate_idempotency_key(idempotency_key)
            if kind in {"task.claim", "executor.register"}:
                self.store.conn.execute(
                    "INSERT INTO session_command_replay(command_kind,aggregate_id,idempotency_key,request_hash,result_json,created_at) "
                    "VALUES (?, ?, ?, ?, ?, ?)",
                    (kind, aggregate_id, idempotency_key, request_hash, canonical_json(result), now()),
                )
                cutoff = (datetime.now(timezone.utc) - timedelta(seconds=SESSION_IDEMPOTENCY_WINDOW_SECONDS)).isoformat(timespec="milliseconds")
                rows = self.store.conn.execute(
                    "SELECT command_kind, aggregate_id, idempotency_key, result_json "
                    "FROM session_command_replay WHERE is_expired=0 AND created_at < ? LIMIT 100",
                    (cutoff,),
                ).fetchall()
                for old in rows:
                    self.store.conn.execute(
                        "UPDATE session_command_replay SET result_json=?, is_expired=1 "
                        "WHERE command_kind=? AND aggregate_id=? AND idempotency_key=?",
                        (expired_command_result(old["result_json"]), old["command_kind"], old["aggregate_id"], old["idempotency_key"]),
                    )
                return result
            if project_id is not None:
                self.store._record_command_receipt(
                    kind, aggregate_id, idempotency_key, request_hash, result,
                    project_id=project_id, event_ids=event_ids,
                    primary_stream_id=primary_stream_id,
                    resulting_stream_seq=resulting_stream_seq,
                    created_at=created_at,
                )
                row = self.store.conn.execute(
                    "SELECT txn_id, command_kind, idempotency_key, request_hash, result_json, "
                    "first_project_seq, last_project_seq, event_ids_json, created_at "
                    "FROM command_idempotency WHERE command_kind=? AND aggregate_id=? AND idempotency_key=?",
                    (kind, aggregate_id, idempotency_key),
                ).fetchone()
                if with_receipt:
                    return {"data": result, "receipt": self._receipt_payload(row, project_id=project_id)}
                return result
            self.store.conn.execute(
                "INSERT INTO command_idempotency(command_kind, aggregate_id, idempotency_key, request_hash, result_json, created_at) VALUES (?, ?, ?, ?, ?, ?)",
                (kind, aggregate_id, idempotency_key, request_hash, compact_result(kind, result), now()),
            )
        return result

    def _open_publication_directory(self, *, create):
        """Open the publication journal directory below pinned staging fds."""
        staging_fd = _open_directory_chain(self.store.staging_root)
        try:
            if create:
                publication_fd = _mkdir_chain_at(staging_fd, "publications")
            else:
                publication_fd = os.open(
                    "publications",
                    os.O_RDONLY | getattr(os, "O_DIRECTORY", 0) | getattr(os, "O_NOFOLLOW", 0),
                    dir_fd=staging_fd,
                )
            try:
                if not stat.S_ISDIR(os.fstat(publication_fd).st_mode):
                    raise ConflictError("publication journal directory is invalid")
            except Exception:
                os.close(publication_fd)
                raise
            return staging_fd, publication_fd
        except Exception:
            os.close(staging_fd)
            raise


    def _begin_cas_publication_journal(self, kind, entries, *, project_id=None, task_id=None):
        """Durably describe CAS destinations before making them reachable.

        The journal is intentionally outside SQLite: a process crash can occur
        after ``rename`` and before the SQLite commit.  Startup then keeps a
        destination only when the durable metadata proves that this operation
        committed; otherwise it removes the exact content-addressed path.
        """
        if not entries:
            return None
        payload = {
            "version": 1,
            "kind": kind,
            "project_id": project_id,
            "task_id": task_id,
            "entries": [{"digest": str(entry["digest"])} for entry in entries],
        }
        journal_name = f"{new_id()}.json"
        staging_fd = publication_fd = -1
        try:
            staging_fd, publication_fd = self._open_publication_directory(create=True)
            _write_bytes_at(publication_fd, journal_name, durable_json_bytes(payload))
            os.fsync(staging_fd)
        finally:
            if publication_fd >= 0:
                os.close(publication_fd)
            if staging_fd >= 0:
                os.close(staging_fd)
        return self.store.staging_root / "publications" / journal_name

    @staticmethod
    def _remove_publication_journal_at(directory_fd, name):
        try:
            os.unlink(name, dir_fd=directory_fd)
        except FileNotFoundError:
            return True
        except OSError:
            return False
        try:
            os.fsync(directory_fd)
        except OSError:
            return False
        return True


    def _publication_committed(self, journal):
        entries = journal.get("entries")
        if not isinstance(entries, list) or not entries:
            return False
        digests = []
        for entry in entries:
            if not isinstance(entry, dict) or not isinstance(entry.get("digest"), str):
                return False
            digest = entry["digest"]
            if len(digest) != 64 or any(char not in "0123456789abcdef" for char in digest):
                return False
            digests.append(digest)
            if not self.store.conn.execute("SELECT 1 FROM objects WHERE digest=?", (digest,)).fetchone():
                return False
        project_id = journal.get("project_id")
        if project_id and project_id != "unscoped":
            for digest in digests:
                if not self.store.conn.execute("SELECT 1 FROM project_objects WHERE project_id=? AND digest=?", (project_id, digest)).fetchone():
                    return False
        if journal.get("kind") == "settlement":
            task_id = journal.get("task_id")
            task = self.store.conn.execute("SELECT status, result_json FROM tasks WHERE id=?", (task_id,)).fetchone()
            if not task or task["status"] != "completed":
                return False
            try:
                result_digests = {
                    str(item.get("digest", "")).removeprefix("sha256:")
                    for item in (json.loads(task["result_json"] or "{}").get("outputs") or [])
                    if isinstance(item, dict)
                }
            except (TypeError, ValueError, json.JSONDecodeError):
                return False
            if not set(digests).issubset(result_digests):
                return False
        return True

    def _recover_cas_publication_journals(self):
        """Finish or roll back CAS publications left by a crashed mutation."""
        staging_fd = publication_fd = -1
        try:
            try:
                staging_fd, publication_fd = self._open_publication_directory(create=False)
            except FileNotFoundError:
                return
            try:
                names = sorted(
                    entry.name
                    for entry in os.scandir(publication_fd)
                    if entry.name.endswith(".json")
                    and not entry.is_symlink()
                    and stat.S_ISREG(entry.stat(follow_symlinks=False).st_mode)
                )
            except OSError:
                return
            for name in names:
                journal_fd = -1
                try:
                    journal_fd = os.open(
                        name,
                        os.O_RDONLY | getattr(os, "O_NOFOLLOW", 0),
                        dir_fd=publication_fd,
                    )
                    chunks = []
                    while True:
                        chunk = os.read(journal_fd, 1024 * 1024)
                        if not chunk:
                            break
                        chunks.append(chunk)
                    journal = json.loads(b"".join(chunks).decode("utf-8"))
                except (OSError, UnicodeDecodeError, json.JSONDecodeError):
                    # Leave malformed evidence for doctor/operator inspection;
                    # do not guess at a path and risk deleting unrelated data.
                    continue
                finally:
                    if journal_fd >= 0:
                        os.close(journal_fd)
                if not isinstance(journal, dict) or journal.get("version") != 1:
                    continue
                try:
                    committed = self._publication_committed(journal)
                except (OSError, sqlite3.DatabaseError, TypeError, ValueError):
                    continue
                if not committed:
                    cleanup_failed = False
                    for entry in journal.get("entries", []):
                        digest = entry.get("digest") if isinstance(entry, dict) else None
                        if not isinstance(digest, str) or len(digest) != 64 or any(char not in "0123456789abcdef" for char in digest):
                            continue
                        # If another operation has since durable-metadata-claimed
                        # this object, it owns the file and it must be retained.
                        if self.store.conn.execute("SELECT 1 FROM objects WHERE digest=?", (digest,)).fetchone():
                            continue
                        try:
                            self._unlink_cas_destination(digest)
                        except (OSError, ConflictError):
                            # Keep durable evidence when the CAS prefix cannot
                            # be opened or its pinned entry cannot be removed.
                            cleanup_failed = True
                            continue
                    if cleanup_failed:
                        continue
                if not self._remove_publication_journal_at(publication_fd, name):
                    continue
        finally:
            if publication_fd >= 0:
                os.close(publication_fd)
            if staging_fd >= 0:
                os.close(staging_fd)

    @staticmethod
    def _revision_digest(payload):
        """Digest the exact canonical JSON bytes persisted for a revision."""
        return "sha256:" + hashlib.sha256(canonical_json(payload).encode("utf-8")).hexdigest()

    @staticmethod
    def _revision_id(value, field):
        if not isinstance(value, str) or not value or len(value) > 256:
            raise ValidationError(f"{field} must be a non-empty revision identity")
        return value

    @staticmethod
    def _revision_payload(entry, *, excluded):
        if not isinstance(entry, dict):
            raise ValidationError("revision entries must be objects")
        payload = entry.get("payload", entry.get("content"))
        if payload is None:
            payload = {key: value for key, value in entry.items() if key not in excluded}
        if not isinstance(payload, dict):
            raise ValidationError("revision payload must be an object")
        return copy.deepcopy(payload)

    @staticmethod
    def _complete_internal_timeline_payload(payload):
        if not isinstance(payload, dict):
            raise ValidationError("internal timeline payload must be an object")
        def contains_nested_composition(value):
            if isinstance(value, dict):
                if set(value) & {"occurrences", "occurrence_records", "shot_revision_id", "parent_revision_id", "composition_revision_id", "nested_composition"}:
                    return True
                return any(contains_nested_composition(item) for item in value.values())
            if isinstance(value, list):
                return any(contains_nested_composition(item) for item in value)
            return False
        if contains_nested_composition(payload):
            raise ValidationError("internal timeline cannot contain a nested composition")
        result = copy.deepcopy(payload)
        aliases = {"local_tracks": "tracks", "local_clips": "clips", "local_effects": "effects", "local_audio": "audio", "local_layout": "layout", "scoped_registry": "registry", "scoped_assets": "assets"}
        for source, target in aliases.items():
            if source in result and target not in result:
                result[target] = result.pop(source)
        defaults = {"tracks": [], "clips": [], "effects": [], "audio": [], "layout": {}, "registry": {}, "assets": []}
        for key, default in defaults.items():
            result.setdefault(key, default)
        RuntimeService._validate_timeline_track_roles(result)
        effects = result["effects"]
        if not isinstance(effects, list):
            raise ValidationError("internal timeline effects must be a list")
        for effect in effects:
            if not isinstance(effect, dict) or effect.get("type") not in SUPPORTED_COMPOSITION_EFFECTS:
                raise ValidationError("unsupported composition effect", details={"effect": effect})
        return result

    @staticmethod
    def _validate_timeline_track_roles(config):
        tracks = config.get("tracks", []) if isinstance(config, dict) else []
        if not isinstance(tracks, list):
            return
        for track in tracks:
            if not isinstance(track, dict) or "role" not in track:
                continue
            if track["role"] not in ("output", "source"):
                raise ValidationError(
                    "timeline track role must be 'output' or 'source'",
                    details={"track_id": track.get("id"), "role": track["role"]},
                )

    @staticmethod
    def _complete_shot_payload(payload, internal_revision_id):
        if not isinstance(payload, dict):
            raise ValidationError("shot revision payload must be an object")
        if any(key in payload for key in ("occurrences", "occurrence_records", "parent_composition", "parent_revision_id", "composition_revision_id")):
            raise ValidationError("shot revision cannot contain a nested composition")
        result = copy.deepcopy(payload)
        aliases = {"item_membership": "items", "item_pool": "pools", "variants": "selected_variants", "generation": "generation_inputs", "audio": "audio_bindings", "text": "text_bindings"}
        for source, target in aliases.items():
            if source in result and target not in result:
                result[target] = result.pop(source)
        defaults = {"metadata": {}, "items": [], "pools": [], "selected_variants": {}, "provenance": {}, "generation_inputs": {}, "audio_bindings": [], "text_bindings": []}
        for key, default in defaults.items():
            result.setdefault(key, default)
        result["internal_timeline_revision_id"] = internal_revision_id
        return result

    @staticmethod
    def _complete_parent_payload(payload):
        if not isinstance(payload, dict):
            raise ValidationError("parent composition payload must be an object")
        result = copy.deepcopy(payload)
        aliases = {"authored_config": "config", "authored_registry": "registry", "ordinary_clips": "clips", "occurrence_records": "occurrences"}
        for source, target in aliases.items():
            if source in result and target not in result:
                result[target] = result.pop(source)
        defaults = {"config": {}, "registry": {}, "clips": [], "occurrences": []}
        for key, default in defaults.items():
            result.setdefault(key, default)
        if not isinstance(result["config"], dict) or not isinstance(result["registry"], dict):
            raise ValidationError("parent composition config and registry must be objects")
        RuntimeService._validate_timeline_track_roles(result["config"])
        if not isinstance(result["clips"], list) or not isinstance(result["occurrences"], list):
            raise ValidationError("parent composition clips and occurrences must be lists")
        for clip in result["clips"]:
            if not isinstance(clip, dict):
                raise ValidationError("ordinary clips must be objects")
            if any(key in clip for key in ("occurrence_id", "shot_revision_id", "parent_revision_id", "composition_revision_id")):
                raise ValidationError("ordinary clips cannot contain nested shot compositions")
            effects = clip.get("effects", [])
            if not isinstance(effects, list):
                raise ValidationError("clip effects must be a list")
            for effect in effects:
                if not isinstance(effect, dict) or effect.get("type") not in SUPPORTED_COMPOSITION_EFFECTS:
                    raise ValidationError("unsupported composition effect", details={"effect": effect})
        return result

    def get_project_shot_revision(self, project_id, shot_id, revision):
        project = self.store.get_project(project_id)
        row = self.store.conn.execute("SELECT * FROM shot_revisions WHERE id=? AND project_id=? AND shot_id=?", (revision, project["id"], shot_id)).fetchone()
        if not row:
            raise NotFoundError("shot revision not found", details={"shot_id": shot_id, "revision": revision})
        return {"revision_id": row["id"], "project_id": row["project_id"], "shot_id": row["shot_id"], "internal_timeline_revision_id": row["internal_timeline_revision_id"], "content_digest": row["content_digest"], "payload": json.loads(row["payload_json"]), "created_at": row["created_at"]}

    def get_project_timeline_revision(self, project_id, timeline_id, revision):
        project = self.store.get_project(project_id)
        row = self.store.conn.execute("SELECT * FROM internal_timeline_revisions WHERE id=? AND project_id=? AND timeline_id=?", (revision, project["id"], timeline_id)).fetchone()
        if not row:
            raise NotFoundError("internal timeline revision not found", details={"timeline_id": timeline_id, "revision": revision})
        return {"revision_id": row["id"], "project_id": row["project_id"], "timeline_id": row["timeline_id"], "content_digest": row["content_digest"], "payload": json.loads(row["payload_json"]), "created_at": row["created_at"]}

    def get_project_timeline(self, project_id, timeline_id):
        """Read one timeline only through its project-scoped identity."""
        project = self.store.get_project(project_id)
        row = self.store.conn.execute(
            "SELECT project_id FROM timelines WHERE id=? AND project_id=?",
            (timeline_id, project["id"]),
        ).fetchone()
        if row is None:
            raise NotFoundError("timeline not found")
        # Same projection as create/rename/list: retired timeline-document bytes (config/registry) stay unserved.
        return self._timeline_public_resource(timeline_id)

    def get_project_parent_composition_revision(self, project_id, timeline_id, revision):
        project = self.store.get_project(project_id)
        row = self.store.conn.execute("SELECT * FROM parent_composition_revisions WHERE id=? AND project_id=? AND timeline_id=?", (revision, project["id"], timeline_id)).fetchone()
        if not row:
            raise NotFoundError("parent composition revision not found", details={"timeline_id": timeline_id, "revision": revision})
        result = {"revision_id": row["id"], "project_id": row["project_id"], "timeline_id": row["timeline_id"], "content_digest": row["content_digest"], "payload": json.loads(row["payload_json"]), "created_at": row["created_at"]}
        # A non-null manifest is the acceptance layer's proof that this
        # immutable revision has a verified closure.  Legacy rows either do
        # not have the column or leave it NULL, so keep their historical read
        # shape instead of guessing pins from mutable payloads.
        if "commit_manifest_json" in row.keys() and row["commit_manifest_json"] is not None:
            result["dependency_manifest"] = json.loads(row["commit_manifest_json"])
        return result

    def list_project_parent_composition_revisions(self, project_id, timeline_id, *, cursor=None, limit=PAGE_DEFAULT_LIMIT):
        """List immutable canonical history for one project timeline."""
        project = self.store.get_project(project_id)
        timeline = self.store.conn.execute(
            "SELECT 1 FROM timelines WHERE id=? AND project_id=?", (timeline_id, project["id"])
        ).fetchone()
        if timeline is None:
            raise NotFoundError("timeline not found", details={"timeline_id": timeline_id, "project_id": project["id"]})
        head = self.store.conn.execute(
            "SELECT revision_id FROM parent_composition_heads WHERE timeline_id=? AND project_id=?",
            (timeline_id, project["id"]),
        ).fetchone()
        current_head = head["revision_id"] if head else None
        rows = self.store.conn.execute(
            "SELECT * FROM parent_composition_revisions WHERE project_id=? AND timeline_id=? ORDER BY created_at DESC, id DESC",
            (project["id"], timeline_id),
        ).fetchall()
        return _page_rows(
            rows,
            scope=f"parent-composition-history:{project['id']}:{timeline_id}",
            cursor=cursor,
            limit=limit,
            key_fn=lambda row: (row["created_at"], row["id"]),
            resource_fn=lambda row: {
                "revision_id": row["id"],
                "project_id": row["project_id"],
                "timeline_id": row["timeline_id"],
                "content_digest": row["content_digest"],
                "created_at": row["created_at"],
                "is_current_head": row["id"] == current_head,
            },
            skip_after=lambda key, after: key >= after,
        )

    def register_timeline_commit_provider(self, provider):
        from .timeline_commit_port import validate_provider
        validate_provider(provider)
        from .timeline_commit import CommitRejected
        with self.store._mutex:
            if self._timeline_commit_started or self._timeline_commit_provider is not None:
                raise ValidationError("timeline provider registration is startup-only")
            commits, _ = self._timeline_commits()
            # Install verified legacy facts before serving requests. Preview
            # and rejected edits must never persist baseline/history rows.
            heads = self.store.conn.execute(
                "SELECT project_id, timeline_id FROM parent_composition_heads "
                "WHERE revision_id IS NOT NULL AND publication_id IS NULL",
            ).fetchall()
            for head in heads:
                try:
                    commits.install_verified_baseline(head["project_id"], head["timeline_id"],
                                                      authorize=self._assert_mutation_admitted)
                except (CommitRejected, ConflictError):
                    pass  # An unprovable existing timeline stays read-only.
            self._timeline_commit_provider = provider

    def _timeline_commits(self):
        from .timeline_commit_validation import validate_commit_value
        from .timeline_commit_execution import CommitExecutionCoordinator
        from .timeline_commit_store import TimelineCommitStore
        with self.store._mutex:
            if self._timeline_commit_store is None:
                self._timeline_commit_store = TimelineCommitStore(
                    self.store, validate_prepared=lambda value: validate_commit_value(value, "PreparedCommit"),
                )
                self._timeline_commit_coordinator = CommitExecutionCoordinator(self._timeline_commit_store)
            return self._timeline_commit_store, self._timeline_commit_coordinator

    def _timeline_authorize(self, project_id, timeline_id, authorize, *, mutation=True,
                            allow_archived=False):
        if not callable(authorize):
            raise AuthorizationError("authenticated timeline authority callback is required")
        def check():
            authorize()
            if mutation:
                self._assert_mutation_admitted()
            project = self.store.get_project(project_id)
            if project["id"] != project_id or project["realm_id"] != self.realm["id"]:
                raise AuthorizationError("canonical project identity is required")
            if timeline_id is not None:
                query = "SELECT 1 FROM timelines WHERE id=? AND project_id=?"
                if not allow_archived:
                    query += " AND archived_at IS NULL"
                row = self.store.conn.execute(query, (timeline_id, project_id)).fetchone()
                if row is None:
                    raise NotFoundError("timeline not found")
        with self.store._mutex:
            check()
        return check

    def commit_timeline(self, project_id, timeline_id, body, *, idempotency_key,
                        publisher, invocation_path, authorize):
        from .timeline_commit_port import detached, route_path, validate_request
        body = detached(body)
        validate_request(body)
        if (body["project_id"], body["timeline_id"]) != (project_id, timeline_id):
            raise ValidationError("commit path and body identities must agree")
        if invocation_path != route_path(project_id, timeline_id):
            raise ValidationError("commit invocation must use its canonical Runtime path")
        return self._execute_timeline_commit(
            project_id, timeline_id, body, body, operation="commitTimeline",
            idempotency_key=idempotency_key, publisher=publisher,
            invocation_path=invocation_path, authorize=authorize,
        )

    def _execute_timeline_commit(self, project_id, timeline_id, request, original_body, *,
                                 operation, idempotency_key, publisher, invocation_path, authorize):
        from .timeline_commit import CommitRejected
        from .timeline_commit_port import CommitUnavailable, RequestCommitPort, detached, public_failure
        if not isinstance(publisher, str) or not publisher:
            raise AuthorizationError("authenticated publisher is required")
        idempotency_key = require_idempotency_key(idempotency_key)
        # A retry must authenticate against the current bearer and canonical
        # project before it can inspect the durable idempotency row.  Archived
        # liveness is deferred until the lookup misses, so an exact replay can
        # still be returned without reopening the mutable producer scope.
        check = self._timeline_authorize(project_id, timeline_id, authorize, allow_archived=True)

        def require_active():
            check()
            with self.store._mutex:
                connection = self.store.conn
                if connection is None:
                    raise RuntimeError("runtime store is not open")
                row = connection.execute(
                    "SELECT 1 FROM timelines WHERE id=? AND project_id=? AND archived_at IS NULL",
                    (timeline_id, project_id),
                ).fetchone()
                if row is None:
                    raise NotFoundError("timeline not found")

        invocation = {"operation": operation, "path": invocation_path, "body": detached(original_body)}
        request_hash = hashlib.sha256(canonical_json({
            "operation": operation, "path": invocation_path,
            "publisher": publisher, "request": invocation["body"],
        }).encode()).hexdigest()
        context = {"request": detached(request), "invocation": invocation,
                   "request_hash": request_hash, "idempotency_key": idempotency_key,
                   "publisher": publisher, "realm_id": self.realm["id"]}
        commits, coordinator = self._timeline_commits()
        with self.store._mutex:
            self._timeline_commit_started = True
            provider = self._timeline_commit_provider
        def port_factory(bound_context):
            require_active()
            self._ensure_timeline_commit_baseline(commits, project_id, timeline_id, require_active)
            return RequestCommitPort(self, commits, bound_context, require_active)
        try:
            if provider is None:
                replay = commits.lookup(context, authorize=check)
                if replay is not None:
                    return replay
                require_active()
                raise CommitUnavailable()
            outcome = coordinator.execute(context, provider, port_factory, authorize=check)
            if "http_status" in outcome:
                raise public_failure(outcome)
            return outcome
        except CommitRejected as exc:
            raise public_failure(exc.failure) from exc
        except (AuthorizationError, ForbiddenError, NotFoundError, ValidationError, ConflictError):
            raise
        except RuntimeErrorBase:
            raise
        except Exception as exc:
            raise CommitUnavailable() from exc

    def _ensure_timeline_commit_baseline(self, commits, project_id, timeline_id, authorize):
        with self.store._mutex:
            authorize()
            row = self.store.conn.execute(
                "SELECT publication_id FROM parent_composition_heads WHERE project_id=? AND timeline_id=?",
                (project_id, timeline_id),
            ).fetchone()
            if row is None or row["publication_id"] is None:
                commits.head(project_id, timeline_id)

    def list_timeline_commits(self, project_id, timeline_id, *, cursor=None,
                              limit=PAGE_DEFAULT_LIMIT, authorize):
        from .timeline_commit import CommitRejected
        from .timeline_commit_port import public_failure
        # The public HTTP query is text, while the commit store deliberately
        # accepts only an already-validated integer.  Keep cursor validation
        # and fixed-head binding in the commit store; this call only normalizes
        # the independent public limit argument.
        limit, _ = _page_args(None, limit)
        check = self._timeline_authorize(project_id, timeline_id, authorize, mutation=False)
        commits, _ = self._timeline_commits()
        try:
            with self.store._mutex:
                check()
                self._ensure_timeline_commit_baseline(commits, project_id, timeline_id, check)
                # The store's opaque cursor includes the original fixed head.
                if cursor is None:
                    through = commits.head(project_id, timeline_id)
                else:
                    try:
                        decoded = json.loads(base64.urlsafe_b64decode(cursor.encode()))
                        scope = decoded["scope"]
                        if scope[:2] != [project_id, timeline_id] or scope[3] is not None:
                            raise ValueError()
                        through = scope[2]
                    except (ValueError, KeyError, TypeError, IndexError) as exc:
                        raise ValidationError("invalid commit history cursor") from exc
                return commits.history(project_id, timeline_id, through, cursor=cursor, limit=limit)
        except CommitRejected as exc:
            raise public_failure(exc.failure) from exc

    def _verified_read(self, project_id, authorize, read):
        from .timeline_commit import CommitRejected
        from .timeline_commit_port import public_failure
        check = self._timeline_authorize(project_id, None, authorize, mutation=False)
        try:
            with self.store._mutex:
                check()
                return read()
        except CommitRejected as exc:
            raise public_failure(exc.failure) from exc

