    @_durable_mutation
    def recover_timeline(self, timeline_id, body, *, idempotency_key=None):
        self._require_object_body(body)
        expected = self._expected_version(body)
        target = body.get("version")
        if "version" in body and (isinstance(target, bool) or not isinstance(target, int) or target < 1):
            raise ValidationError("version must be a positive integer when provided")
        current = self._timeline_resource(timeline_id)
        project_id = str(current["project_id"])
        request_hash = hashlib.sha256(canonical_json({
            "timeline_id": timeline_id, "body": body, "action": "recover",
        }).encode()).hexdigest()
        # This operation is catalog visibility only.  An exact receipt from
        # this implementation remains replayable, but only when its event
        # proves that it was the visibility-only operation.  Check this before
        # the ordinary replay path so absent and current-target retries cannot
        # replay a legacy flat-projection write.
        safe_receipt = self.store.conn.execute(
            "SELECT event_ids_json, primary_stream_id FROM command_idempotency "
            "WHERE command_kind=? AND aggregate_id=? AND idempotency_key=? "
            "AND request_hash=?",
            ("timeline.recover", timeline_id, idempotency_key, request_hash),
        ).fetchone() if idempotency_key is not None else None
        if safe_receipt:
            event_ids = None
            event = None
            payload = None
            try:
                event_ids = json.loads(safe_receipt["event_ids_json"] or "[]")
                if (safe_receipt["primary_stream_id"] == timeline_id
                        and isinstance(event_ids, list) and len(event_ids) == 1
                        and isinstance(event_ids[0], str) and event_ids[0]):
                    event = self.store.conn.execute(
                        "SELECT kind, payload_json FROM timeline_events "
                        "WHERE id=? AND timeline_id=?",
                        (event_ids[0], timeline_id),
                    ).fetchone()
                payload = json.loads(event["payload_json"]) if event else None
            except (TypeError, ValueError, json.JSONDecodeError):
                event_ids = None
                payload = None
            event_version = payload.get("version") if isinstance(payload, dict) else None
            if (event and event["kind"] == "timeline.recovered"
                    and isinstance(payload, dict)
                    and set(payload) == {"project_id", "version"}
                    and payload["project_id"] == project_id
                    and not isinstance(event_version, bool)
                    and isinstance(event_version, int) and event_version > 0
                    and event_version == expected + 1):
                replay = self._command_replay(
                    "timeline.recover", timeline_id, idempotency_key,
                    request_hash, project_id=project_id,
                )
                if replay is not None:
                    return replay
            raise RetiredRouteError(
                "legacy timeline recover cannot restore a historical film version; restore a revision with timeline.restore",
                details={
                    "status": "refused", "reason": "timeline_restore_required",
                    "replacement": "timeline.restore", "requested_version": target,
                    "current_version": current["version"],
                },
            )
        # A historical target is the retired flat-projection writer; canonical
        # history is restored by the recorded timeline.restore command.
        if target is not None and target != current["version"]:
            raise RetiredRouteError(
                "legacy timeline recover cannot restore a historical film version; restore a revision with timeline.restore",
                details={
                    "status": "refused", "reason": "timeline_restore_required",
                    "replacement": "timeline.restore", "requested_version": target,
                    "current_version": current["version"],
                },
            )
        replay = self._command_replay(
            "timeline.recover", timeline_id, idempotency_key, request_hash,
            project_id=project_id,
        )
        if replay is not None:
            return replay
        if current["version"] != expected:
            raise ConflictError(
                "timeline version conflict",
                details={"expected": expected, "actual": current["version"]},
            )
        self.store.conn.execute(
            "UPDATE timelines SET archived_at=NULL, version=? WHERE id=?",
            (expected + 1, timeline_id),
        )
        resource = self._timeline_resource(timeline_id)
        event_id = self.store._append_timeline_event(
            timeline_id, "timeline.recovered", {
                "project_id": project_id, "version": resource["version"],
            },
        )
        event_seq = self.store.conn.execute(
            "SELECT COUNT(*) FROM timeline_events WHERE timeline_id=?",
            (timeline_id,),
        ).fetchone()[0]
        return self._command_record(
            "timeline.recover", timeline_id, idempotency_key, request_hash,
            resource, project_id=project_id, event_ids=(event_id,),
            primary_stream_id=timeline_id, resulting_stream_seq=event_seq,
        )

    def get_shot(self, shot_id):
        row = self.store.conn.execute("SELECT * FROM timeline_shots WHERE id=?", (shot_id,)).fetchone()
        if not row: raise NotFoundError("shot not found")
        return self._shot_resource(row)

    @_durable_mutation
    def create_reference(self, timeline_id, body, *, idempotency_key=None):
        self._require_timeline_command()

    PREFERENCE_DOCUMENT_KIND = "astrid.preferences"
    PROJECT_PREFERENCE_PREFIX = "preferences:project:"

    @classmethod
    def _validate_preference_document(cls, project_id, document_id, kind, content):
        reserved = document_id.startswith(cls.PROJECT_PREFERENCE_PREFIX)
        if reserved or kind == cls.PREFERENCE_DOCUMENT_KIND:
            if document_id != cls.PROJECT_PREFERENCE_PREFIX + project_id:
                raise ValidationError("project preference document identity is reserved for its owning project")
            if kind != cls.PREFERENCE_DOCUMENT_KIND:
                raise ValidationError("project preference document kind is reserved")
            if not isinstance(content, str):
                raise ValidationError("preference content must be a Markdown string")

    def _preference_target(self, scope, project_id, identity):
        if scope not in ("user", "project"):
            raise ValidationError("preference scope must be user or project")
        actor = identity.get("actor") if isinstance(identity, dict) else None
        if not isinstance(actor, str) or not actor:
            raise AuthorizationError("authenticated actor is required")
        if scope == "user":
            if project_id is not None:
                raise ValidationError("user preferences do not accept a project selector")
            return actor, None, "preferences:user:" + actor
        if project_id is None:
            project = self.store.current_project(actor)["project"]
        else:
            project = self.store.get_project(project_id)
        return actor, project["id"], self.PROJECT_PREFERENCE_PREFIX + project["id"]

    @staticmethod
    def _preference_resource(scope, actor, project_id, document_id, row):
        return {
            "scope": scope, "actor_id": actor if scope == "user" else None,
            "project_id": project_id, "document_id": document_id,
            "content": (row["content"] if scope == "user" else json.loads(row["content_json"])) if row else "",
            "version": int(row["version"]) if row else 0,
            "created_at": row["created_at"] if row else None,
            "updated_at": row["updated_at"] if row else None,
        }

    def get_preferences(self, scope, project_id=None, *, identity):
        # Serialize the shared connection read so no caller observes another
        # handler's uncommitted write; absent reads have no side effects.
        with self.store._mutex:
            actor, project_id, document_id = self._preference_target(scope, project_id, identity)
            if scope == "user":
                row = self.store.conn.execute("SELECT * FROM user_preferences WHERE actor_id=?", (actor,)).fetchone()
            else:
                row = self.store.conn.execute("SELECT * FROM project_documents WHERE project_id=? AND id=?", (project_id, document_id)).fetchone()
                if row:
                    self._validate_preference_document(project_id, document_id, row["kind"], json.loads(row["content_json"]))
            return self._preference_resource(scope, actor, project_id, document_id, row)

    @_durable_mutation
    def update_preferences(self, scope, content, expected_version, idempotency_key, project_id=None, *, identity):
        actor, project_id, document_id = self._preference_target(scope, project_id, identity)
        require_idempotency_key(idempotency_key)
        if not isinstance(content, str):
            raise ValidationError("preference content must be a Markdown string")
        if isinstance(expected_version, bool) or not isinstance(expected_version, int) or expected_version < 0:
            raise ValidationError("expected_version must be a non-negative integer")
        request = {"scope": scope, "owner": actor if scope == "user" else project_id,
                   "content": content, "expected_version": expected_version}
        request_hash = hashlib.sha256(canonical_json(request).encode()).hexdigest()
        # The actor is part of the aggregate, not a caller-controlled field.
        aggregate_id = document_id
        replay = self._command_replay("preferences.update", aggregate_id, idempotency_key, request_hash, project_id=project_id)
        if replay is not None:
            return replay
        current = self.get_preferences(scope, project_id, identity=identity)
        if current["version"] != expected_version:
            raise ConflictError("preference version conflict", details={"expected": expected_version, "actual": current["version"]})
        timestamp = now()
        if scope == "user":
            if expected_version == 0:
                self.store.conn.execute("INSERT INTO user_preferences(actor_id, id, content, version, created_at, updated_at) VALUES (?, ?, ?, 1, ?, ?)", (actor, document_id, content, timestamp, timestamp))
            else:
                self.store.conn.execute("UPDATE user_preferences SET content=?, version=?, updated_at=? WHERE actor_id=?", (content, expected_version + 1, timestamp, actor))
        elif expected_version == 0:
            self.store.conn.execute("INSERT INTO project_documents VALUES (?, ?, ?, ?, 1, ?, ?)", (document_id, project_id, self.PREFERENCE_DOCUMENT_KIND, canonical_json(content), timestamp, timestamp))
        else:
            self.store.conn.execute("UPDATE project_documents SET content_json=?, version=?, updated_at=? WHERE project_id=? AND id=?", (canonical_json(content), expected_version + 1, timestamp, project_id, document_id))
        result = self.get_preferences(scope, project_id, identity=identity)
        if scope == "user":
            # A user command has neither a project sequence nor project receipt.
            return self._command_record("preferences.update", aggregate_id, idempotency_key, request_hash, {"data": result, "receipt": None})
        return self._command_record("preferences.update", aggregate_id, idempotency_key, request_hash, result, project_id=project_id)

    APP_STATE_KEY_PATTERN = re.compile(r"[a-z0-9][a-z0-9._-]{0,63}")
    APP_STATE_MAX_BYTES = 16 * 1024

    def _app_state_target(self, key, identity):
        actor = identity.get("actor") if isinstance(identity, dict) else None
        if not isinstance(actor, str) or not actor:
            raise AuthorizationError("authenticated actor is required")
        if not isinstance(key, str) or not self.APP_STATE_KEY_PATTERN.fullmatch(key):
            raise ValidationError("app-state key must be 1-64 characters of a-z, 0-9, '.', '_' or '-' and start with a letter or digit")
        return actor

    @staticmethod
    def _app_state_resource(key, actor, row):
        return {
            "scope": "user", "actor_id": actor, "key": key,
            "content": json.loads(row["content_json"]) if row else None,
            "version": int(row["version"]) if row else 0,
            "created_at": row["created_at"] if row else None,
            "updated_at": row["updated_at"] if row else None,
        }

    def get_app_state(self, key, *, identity):
        # Absent state reads as version zero and writes nothing.
        with self.store._mutex:
            actor = self._app_state_target(key, identity)
            row = self.store.conn.execute("SELECT * FROM user_app_state WHERE actor_id=? AND key=?", (actor, key)).fetchone()
            return self._app_state_resource(key, actor, row)

    @_durable_mutation
    def update_app_state(self, key, content, expected_version, idempotency_key, *, identity):
        actor = self._app_state_target(key, identity)
        require_idempotency_key(idempotency_key)
        if not isinstance(content, dict):
            raise ValidationError("app-state content must be a JSON object")
        if isinstance(expected_version, bool) or not isinstance(expected_version, int) or expected_version < 0:
            raise ValidationError("expected_version must be a non-negative integer")
        encoded = canonical_json(content)
        if len(encoded.encode("utf-8")) > self.APP_STATE_MAX_BYTES:
            raise ValidationError(f"app-state content exceeds {self.APP_STATE_MAX_BYTES} bytes")
        aggregate_id = f"app-state:user:{actor}:{key}"
        request_hash = hashlib.sha256(canonical_json({"owner": actor, "key": key, "content": content, "expected_version": expected_version}).encode()).hexdigest()
        replay = self._command_replay("app_state.update", aggregate_id, idempotency_key, request_hash)
        if replay is not None:
            return replay
        current = self.get_app_state(key, identity=identity)
        if current["version"] != expected_version:
            raise ConflictError("app-state version conflict", details={"expected": expected_version, "actual": current["version"]})
        timestamp = now()
        if expected_version == 0:
            self.store.conn.execute("INSERT INTO user_app_state(actor_id, key, content_json, version, created_at, updated_at) VALUES (?, ?, ?, 1, ?, ?)", (actor, key, encoded, timestamp, timestamp))
        else:
            self.store.conn.execute("UPDATE user_app_state SET content_json=?, version=?, updated_at=? WHERE actor_id=? AND key=?", (encoded, expected_version + 1, timestamp, actor, key))
        result = self.get_app_state(key, identity=identity)
        return self._command_record("app_state.update", aggregate_id, idempotency_key, request_hash, {"data": result, "receipt": None})

    @staticmethod
    def _transcript_document_id(project_id, media_id, source_id):
        # The array order and UTF-8 encoding are part of the cross-client ID
        # contract. canonical_json is compact and leaves Unicode unescaped.
        identity = [TRANSCRIPT_DOCUMENT_SCHEMA, project_id, media_id, source_id]
        digest = hashlib.sha256(canonical_json(identity).encode("utf-8")).hexdigest()
        return TRANSCRIPT_DOCUMENT_PREFIX + digest

    @staticmethod
    def _transcript_string(value, field, limit, *, nonempty=True):
        if not isinstance(value, str) or (nonempty and not value.strip()):
            raise ValidationError(f"transcript {field} must be a non-empty string")
        try:
            size = len(value.encode("utf-8"))
        except UnicodeEncodeError as exc:
            raise ValidationError(f"transcript {field} must be valid Unicode") from exc
        if size > limit:
            raise ValidationError(f"transcript {field} exceeds {limit} UTF-8 bytes")
        return value

    @staticmethod
    def _transcript_time(value, field):
        if isinstance(value, bool) or not isinstance(value, (int, float)):
            raise ValidationError(f"transcript {field} must be a finite number")
        if (isinstance(value, float) and not math.isfinite(value)) or value < 0 or value > TRANSCRIPT_MAX_TIME_SECONDS:
            raise ValidationError(f"transcript {field} must be between 0 and {TRANSCRIPT_MAX_TIME_SECONDS} seconds")
        return float(value)

    def _validate_transcript_document(self, project_id, document_id, kind, content):
        is_reserved = document_id.startswith(TRANSCRIPT_DOCUMENT_PREFIX) or kind == TRANSCRIPT_DOCUMENT_KIND
        if not is_reserved:
            return
        if kind != TRANSCRIPT_DOCUMENT_KIND or not document_id.startswith(TRANSCRIPT_DOCUMENT_PREFIX):
            raise ValidationError("transcript document kind and reserved identity must be used together")
        if not isinstance(content, dict) or set(content) != {"schema", "media_id", "source_id", "segments"}:
            raise ValidationError("transcript content must have the canonical media.transcript/v1 fields")
        if content.get("schema") != TRANSCRIPT_DOCUMENT_SCHEMA:
            raise ValidationError("unsupported transcript content schema")

        media_id = content.get("media_id")
        if not isinstance(media_id, str) or not media_id.startswith("sha256:") or not OBJECT_ID_RE.fullmatch(media_id):
            raise ValidationError("transcript media_id must be a canonical sha256 object id")
        source_id = self._transcript_string(content.get("source_id"), "source_id", TRANSCRIPT_SOURCE_ID_MAX_BYTES)
        if document_id != self._transcript_document_id(project_id, media_id, source_id):
            raise ValidationError("transcript document identity does not match its project, media, and source")

        segments = content.get("segments")
        if not isinstance(segments, list) or len(segments) > TRANSCRIPT_MAX_SEGMENTS:
            raise ValidationError(f"transcript segments must be an array of at most {TRANSCRIPT_MAX_SEGMENTS} items")
        segment_ids = set()
        word_ids = set()
        total_words = 0
        for index, segment in enumerate(segments):
            if not isinstance(segment, dict) or set(segment) - {"id", "start", "end", "text", "speaker", "words"} or not {"id", "start", "end", "text"}.issubset(segment):
                raise ValidationError(f"transcript segment {index} has an invalid shape")
            segment_id = self._transcript_string(segment["id"], f"segments[{index}].id", TRANSCRIPT_ID_MAX_BYTES)
            if segment_id in segment_ids:
                raise ValidationError("transcript segment IDs must be unique")
            segment_ids.add(segment_id)
            start = self._transcript_time(segment["start"], f"segments[{index}].start")
            end = self._transcript_time(segment["end"], f"segments[{index}].end")
            if end < start:
                raise ValidationError(f"transcript segment {index} end must not precede start")
            self._transcript_string(segment["text"], f"segments[{index}].text", TRANSCRIPT_TEXT_MAX_BYTES)
            if "speaker" in segment and segment["speaker"] is not None:
                self._transcript_string(segment["speaker"], f"segments[{index}].speaker", TRANSCRIPT_ID_MAX_BYTES)
            words = segment.get("words", [])
            if not isinstance(words, list):
                raise ValidationError(f"transcript segment {index} words must be an array")
            total_words += len(words)
            if total_words > TRANSCRIPT_MAX_WORDS:
                raise ValidationError(f"transcript must contain at most {TRANSCRIPT_MAX_WORDS} words")
            for word_index, word in enumerate(words):
                if not isinstance(word, dict) or set(word) != {"id", "start", "end", "text"}:
                    raise ValidationError(f"transcript word {index}:{word_index} has an invalid shape")
                word_id = self._transcript_string(word["id"], f"segments[{index}].words[{word_index}].id", TRANSCRIPT_ID_MAX_BYTES)
                if word_id in word_ids:
                    raise ValidationError("transcript word IDs must be unique within the document")
                word_ids.add(word_id)
                word_start = self._transcript_time(word["start"], f"segments[{index}].words[{word_index}].start")
                word_end = self._transcript_time(word["end"], f"segments[{index}].words[{word_index}].end")
                if word_end < word_start or word_start < start or word_end > end:
                    raise ValidationError(f"transcript word {index}:{word_index} timing must fit within its segment")
                self._transcript_string(word["text"], f"segments[{index}].words[{word_index}].text", TRANSCRIPT_TEXT_MAX_BYTES)

        try:
            encoded = canonical_json(content).encode("utf-8")
        except (TypeError, ValueError, UnicodeEncodeError) as exc:
            raise ValidationError("transcript content must be canonical UTF-8 JSON") from exc
        if len(encoded) > TRANSCRIPT_MAX_BYTES:
            raise ValidationError(f"transcript content exceeds {TRANSCRIPT_MAX_BYTES} bytes")
        digest = media_id.removeprefix("sha256:")
        owned = self.store.conn.execute(
            "SELECT 1 FROM objects o JOIN project_objects po ON po.digest=o.digest "
            "WHERE o.digest=? AND po.project_id=? AND po.relation='managed'",
            (digest, project_id),
        ).fetchone()
        if not owned:
            raise ValidationError("transcript source media is not managed by the target project", details={"reason": "media_not_owned", "media_id": media_id})

    def _validate_project_document(self, project_id, document_id, kind, content):
        self._validate_preference_document(project_id, document_id, kind, content)
        self._validate_transcript_document(project_id, document_id, kind, content)
        from .timeline_commit_inputs import PROJECT_PACK_KIND, validate_pack_snapshot_objects
        if kind == PROJECT_PACK_KIND:
            validate_pack_snapshot_objects(self.store.conn, project_id, content)

    def _document_resource(self, row):
        content = json.loads(row["content_json"])
        self._validate_project_document(row["project_id"], row["id"], row["kind"], content)
        value = dict(row)
        value["document_id"] = value.pop("id")
        value.pop("content_json")
        value["content"] = content
        return value

    @staticmethod
    def _reject_canonical_document_write(document_id, kind, *, carries_timeline_id=False):
        if carries_timeline_id or str(document_id).startswith("timeline:") or kind == "timeline.composition":
            RuntimeService._require_timeline_command()

    @_durable_mutation
    def create_document(self, project_id, body, *, idempotency_key=None):
        self._require_object_body(body)
        project = self.store.get_project(project_id)
        document_id = str(body.get("document_id") or "")
        kind = str(body.get("kind") or "")
        if not document_id or not kind or "content" not in body:
            raise ValidationError("document_id, kind, and content are required")
        self._reject_canonical_document_write(
            document_id, kind, carries_timeline_id="timeline_id" in body,
        )
        existing = self.store.conn.execute("SELECT * FROM project_documents WHERE project_id=? AND id=?", (project["id"], document_id)).fetchone()
        if existing:
            self._reject_canonical_document_write(existing["id"], existing["kind"])
        content = body["content"]
        self._validate_project_document(project["id"], document_id, kind, content)
        request_hash = hashlib.sha256(canonical_json({"project_id": project["id"], "document_id": document_id, "kind": kind, "content": content}).encode()).hexdigest()
        replay = self._command_replay("document.create", document_id, idempotency_key, request_hash, project_id=project["id"])
        if replay is not None:
            return replay
        if existing:
            if existing["kind"] == kind and json.loads(existing["content_json"]) == content:
                return self._command_record("document.create", document_id, idempotency_key, request_hash, self._document_resource(existing), project_id=project["id"])
            raise ConflictError("document already exists", details={"document_id": document_id})
        timestamp = now()
        self.store.conn.execute("INSERT INTO project_documents VALUES (?, ?, ?, ?, 1, ?, ?)", (document_id, project["id"], kind, canonical_json(content), timestamp, timestamp))
        result = self._document_resource(self.store.conn.execute("SELECT * FROM project_documents WHERE id=?", (document_id,)).fetchone())
        return self._command_record("document.create", document_id, idempotency_key, request_hash, result, project_id=project["id"])

    def list_documents(self, project_id, *, cursor=None, limit=PAGE_DEFAULT_LIMIT, kind=None):
        project = self.store.get_project(project_id)
        # Timeline composition documents are immutable recovery material, not
        # a public document authority. Keep ordinary project documents
        # listable while forcing timeline callers through inspectTimeline.
        rows = self.store.conn.execute(
            "SELECT * FROM project_documents WHERE project_id=? AND id NOT LIKE 'timeline:%' AND (? IS NULL OR kind=?) ORDER BY created_at, id",
            (project["id"], kind, kind),
        ).fetchall()
        return _page_rows(rows, scope=f"documents:{project['id']}" if kind is None else canonical_json({"documents": project["id"], "kind": kind}), cursor=cursor, limit=limit,
                          key_fn=lambda row: (str(row["created_at"]), str(row["id"])),
                          resource_fn=self._document_resource)

    def get_document(self, project_id, document_id):
        project = self.store.get_project(project_id)
        row = self.store.conn.execute("SELECT * FROM project_documents WHERE project_id=? AND id=?", (project["id"], document_id)).fetchone()
        if not row:
            raise NotFoundError("document not found")
        return self._document_resource(row)

    @_durable_mutation
    def update_document(self, project_id, document_id, body, *, idempotency_key=None):
        self._require_object_body(body)
        expected = self._expected_version(body)
        project = self.store.get_project(project_id)
        carries_timeline_id = "timeline_id" in body
        self._reject_canonical_document_write(
            document_id, body.get("kind"), carries_timeline_id=carries_timeline_id,
        )
        self._reject_canonical_document_write(
            body.get("document_id", document_id), body.get("kind"),
            carries_timeline_id=carries_timeline_id,
        )
        row = self.store.conn.execute("SELECT * FROM project_documents WHERE project_id=? AND id=?", (project["id"], document_id)).fetchone()
        if row:
            self._reject_canonical_document_write(row["id"], row["kind"])
        request_hash = hashlib.sha256(canonical_json({"project_id": project["id"], "document_id": document_id, "body": body}).encode()).hexdigest()
        replay = self._command_replay("document.update", document_id, idempotency_key, request_hash, project_id=project["id"])
        if replay is not None:
            return replay
        if not row:
            raise NotFoundError("document not found")
        if int(row["version"]) != expected:
            raise ConflictError("document version conflict", details={"expected": expected, "actual": int(row["version"])})
        kind = str(body.get("kind", row["kind"]))
        content = body.get("content", json.loads(row["content_json"]))
        if not kind:
            raise ValidationError("document kind is required")
        previous_content = json.loads(row["content_json"])
        self._validate_project_document(project["id"], document_id, row["kind"], previous_content)
        self._validate_project_document(project["id"], document_id, kind, content)
        if row["kind"] == TRANSCRIPT_DOCUMENT_KIND or kind == TRANSCRIPT_DOCUMENT_KIND or document_id.startswith(TRANSCRIPT_DOCUMENT_PREFIX):
            if kind != row["kind"] or kind != TRANSCRIPT_DOCUMENT_KIND:
                raise ValidationError("transcript document kind is immutable")
            if "document_id" in body and body["document_id"] != document_id:
                raise ValidationError("transcript document identity is immutable")
            if content["media_id"] != previous_content["media_id"] or content["source_id"] != previous_content["source_id"]:
                raise ValidationError("transcript media_id and source_id are immutable")
        if document_id.startswith(self.PROJECT_PREFERENCE_PREFIX) and body.get("document_id", document_id) != document_id:
            raise ValidationError("project preference document identity is reserved")
        timestamp = now()
        self.store.conn.execute("UPDATE project_documents SET kind=?, content_json=?, version=?, updated_at=? WHERE id=?", (kind, canonical_json(content), expected + 1, timestamp, document_id))
        result = self._document_resource(self.store.conn.execute("SELECT * FROM project_documents WHERE id=?", (document_id,)).fetchone())
        return self._command_record("document.update", document_id, idempotency_key, request_hash, result, project_id=project["id"])

    def _generation_resource(self, row):
        value = dict(row)
        value["generation_id"] = value.pop("id")
        value["metadata"] = json.loads(value.pop("metadata_json"))
        return value

    @_durable_mutation
    def create_generation(self, project_id, body, *, idempotency_key=None):
        raise ConflictError(
            "direct generation publication is disabled; use an admitted GEN D1 settlement effect"
        )
        self._require_object_body(body)
        project = self.store.get_project(project_id)
        generation_id = str(body.get("generation_id") or "")
        if not generation_id:
            raise ValidationError("generation_id is required")
        metadata = body.get("metadata", {})
        if not isinstance(metadata, dict):
            raise ValidationError("generation metadata must be an object")
        generation_type = str(body.get("type", "generation"))
        status = str(body.get("status", "created"))
        source_task_id = body.get("source_task_id")
        request_hash = hashlib.sha256(canonical_json({"project_id": project["id"], "generation_id": generation_id, "source_task_id": source_task_id, "type": generation_type, "status": status, "metadata": metadata}).encode()).hexdigest()
        replay = self._command_replay("generation.create", generation_id, idempotency_key, request_hash, project_id=project["id"])
        if replay is not None:
            return replay
        try:
            self.store.conn.execute("INSERT INTO generations(id, project_id, source_task_id, type, status, metadata_json, version, created_at, updated_at) VALUES (?, ?, ?, ?, ?, ?, 1, ?, ?)", (generation_id, project["id"], source_task_id, generation_type, status, canonical_json(metadata), now(), now()))
        except sqlite3.IntegrityError as exc:
            raise ConflictError("generation already exists", details={"generation_id": generation_id}) from exc
        result = self._generation_resource(self.store.conn.execute("SELECT * FROM generations WHERE id=?", (generation_id,)).fetchone())
        return self._command_record("generation.create", generation_id, idempotency_key, request_hash, result, project_id=project["id"])

    def list_generations(self, project_id, *, cursor=None, limit=PAGE_DEFAULT_LIMIT):
        project = self.store.get_project(project_id)
        rows = self.store.conn.execute("SELECT * FROM generations WHERE project_id=? ORDER BY created_at DESC, id ASC", (project["id"],)).fetchall()
        return _page_rows(rows, scope=f"generations:{project['id']}", cursor=cursor, limit=limit,
                          key_fn=lambda row: (str(row["created_at"]), str(row["id"])),
                          resource_fn=self._generation_resource,
                          skip_after=lambda key, after: (
                              key[0] > after[0]
                              or (key[0] == after[0] and key[1] <= after[1])
                          ))

    def get_generation(self, generation_id):
        row = self.store.conn.execute("SELECT * FROM generations WHERE id=?", (generation_id,)).fetchone()
        if not row:
            raise NotFoundError("generation not found")
        return self._generation_resource(row)

    @_durable_mutation
    def create_variant(self, generation_id, body, *, idempotency_key=None):
        raise ConflictError(
            "direct variant publication is disabled; use an admitted GEN D1 settlement effect"
        )
        self._require_object_body(body)
        generation = self.get_generation(generation_id)
        variant_id = str(body.get("variant_id") or "")
        if not variant_id:
            raise ValidationError("variant_id is required")
        metadata = body.get("metadata", {})
        if not isinstance(metadata, dict):
            raise ValidationError("variant metadata must be an object")
        object_id = body.get("object_id")
        if object_id:
            object_id = str(object_id).removeprefix("sha256:")
            if not self.store.conn.execute("SELECT 1 FROM objects WHERE digest=?", (object_id,)).fetchone():
                raise NotFoundError("object not found")
        variant_type = str(body.get("variant_type", "original"))
        request_hash = hashlib.sha256(canonical_json({"generation_id": generation_id, "variant_id": variant_id, "object_id": object_id, "variant_type": variant_type, "metadata": metadata}).encode()).hexdigest()
        replay = self._command_replay("variant.create", variant_id, idempotency_key, request_hash, project_id=generation["project_id"])
        if replay is not None:
            return replay
        try:
            self.store.conn.execute(
                "INSERT INTO generation_variants(id, generation_id, object_id, variant_type, metadata_json, thumbnail_object_id, thumbnail_source_object_id, thumbnail_recipe_version, viewed_at, created_at) VALUES (?, ?, ?, ?, ?, NULL, NULL, NULL, NULL, ?)",
                (variant_id, generation_id, object_id, variant_type, canonical_json(metadata), now()),
            )
        except sqlite3.IntegrityError as exc:
            raise ConflictError("generation variant already exists", details={"variant_id": variant_id}) from exc
        result = self._variant_resource(self.store.conn.execute("SELECT * FROM generation_variants WHERE id=?", (variant_id,)).fetchone())
        return self._command_record("variant.create", variant_id, idempotency_key, request_hash, result, project_id=generation["project_id"])

    @staticmethod
    def _variant_resource(row):
        value = dict(row)
        value["variant_id"] = value.pop("id")
        value["metadata"] = json.loads(value.pop("metadata_json"))
        if value.get("object_id"):
            value["object_id"] = "sha256:" + value["object_id"]
        thumbnail_object_id = value.pop("thumbnail_object_id", None)
        thumbnail_source_object_id = value.pop("thumbnail_source_object_id", None)
        thumbnail_recipe_version = value.pop("thumbnail_recipe_version", None)
        if thumbnail_object_id and thumbnail_source_object_id and thumbnail_recipe_version is not None:
            value["thumbnail"] = {
                "object_id": "sha256:" + str(thumbnail_object_id),
                "source_object_id": "sha256:" + str(thumbnail_source_object_id),
                "recipe_version": int(thumbnail_recipe_version),
            }
        else:
            value["thumbnail"] = None
        return value

    def list_variants(self, generation_id, *, cursor=None, limit=PAGE_DEFAULT_LIMIT):
        self.get_generation(generation_id)
        rows = self.store.conn.execute("SELECT * FROM generation_variants WHERE generation_id=? ORDER BY created_at, id", (generation_id,)).fetchall()
        return _page_rows(rows, scope=f"variants:{generation_id}", cursor=cursor, limit=limit,
                          key_fn=lambda row: (str(row["created_at"]), str(row["id"])),
                          resource_fn=self._variant_resource)

    def get_variant(self, variant_id):
        row = self.store.conn.execute("SELECT * FROM generation_variants WHERE id=?", (variant_id,)).fetchone()
        if not row:
            raise NotFoundError("generation variant not found")
        return self._variant_resource(row)

    @_durable_mutation
    def attach_variant_thumbnail(self, variant_id, body, *, idempotency_key=None):
        """Attach a source-verified managed JPEG poster to one variant."""
        if not idempotency_key:
            raise InvalidRequestError("Idempotency-Key is required for state mutations")
        self._require_object_body(body)
        if set(body) != {"thumbnail_object_id", "source_object_id", "recipe_version"}:
            raise ValidationError(
                "variant thumbnail requires thumbnail_object_id, source_object_id, and recipe_version"
            )
        thumbnail_object_id = body["thumbnail_object_id"]
        source_object_id = body["source_object_id"]
        recipe_version = body["recipe_version"]
        for field, value in (("thumbnail_object_id", thumbnail_object_id), ("source_object_id", source_object_id)):
            if not isinstance(value, str) or not OBJECT_ID_RE.fullmatch(value) or not value.startswith("sha256:"):
                raise ValidationError(f"{field} must be a canonical sha256 object id")
        if isinstance(recipe_version, bool) or recipe_version != 1:
            raise ValidationError("recipe_version must be 1")
        row = self.store.conn.execute(
            "SELECT gv.*, g.project_id FROM generation_variants gv JOIN generations g ON g.id=gv.generation_id WHERE gv.id=?",
            (variant_id,),
        ).fetchone()
        if not row:
            raise NotFoundError("generation variant not found")
        source_digest = source_object_id.removeprefix("sha256:")
        thumbnail_digest = thumbnail_object_id.removeprefix("sha256:")
        if row["object_id"] != source_digest:
            raise ConflictError(
                "variant source changed before thumbnail attachment",
                details={"variant_id": str(variant_id), "expected_source_object_id": "sha256:" + str(row["object_id"]), "actual_source_object_id": source_object_id},
            )
        project_id = str(row["project_id"])
        thumbnail_row = self.store.conn.execute(
            "SELECT media_type FROM objects WHERE digest=?", (thumbnail_digest,)
        ).fetchone()
        if not thumbnail_row:
            raise NotFoundError("thumbnail object not found")
        if str(thumbnail_row["media_type"]).lower() != "image/jpeg":
            raise ConflictError("variant thumbnail object must be image/jpeg")
        if not self.store.conn.execute(
            "SELECT 1 FROM project_objects WHERE project_id=? AND digest=?",
            (project_id, thumbnail_digest),
        ).fetchone():
            raise ConflictError("thumbnail object is outside the variant project")
        request_hash = hashlib.sha256(canonical_json({"variant_id": str(variant_id), **body}).encode()).hexdigest()
        replay = self._command_replay(
            "variant.thumbnail.attach", str(variant_id), idempotency_key, request_hash,
            project_id=project_id,
        )
        if replay is not None:
            return replay
        self.store.conn.execute(
            "UPDATE generation_variants SET thumbnail_object_id=?, thumbnail_source_object_id=?, thumbnail_recipe_version=? WHERE id=? AND object_id=?",
            (thumbnail_digest, source_digest, recipe_version, variant_id, source_digest),
        )
        updated = self.store.conn.execute(
            "SELECT * FROM generation_variants WHERE id=?", (variant_id,)
        ).fetchone()
        return self._command_record(
            "variant.thumbnail.attach", str(variant_id), idempotency_key,
            request_hash, self._variant_resource(updated), project_id=project_id,
        )

    @_durable_mutation
    def mark_variant_viewed(self, variant_id, *, idempotency_key=None):
        """Persist the first lightbox view for one Runtime-owned variant."""
        if not idempotency_key:
            raise InvalidRequestError("Idempotency-Key is required for state mutations")
        row = self.store.conn.execute(
            "SELECT gv.*, g.project_id FROM generation_variants gv JOIN generations g ON g.id=gv.generation_id WHERE gv.id=?",
            (variant_id,),
        ).fetchone()
        if not row:
            raise NotFoundError("generation variant not found")
        project_id = str(row["project_id"])
        request_hash = hashlib.sha256(canonical_json({"variant_id": str(variant_id)}).encode()).hexdigest()
        replay = self._command_replay(
            "variant.view", str(variant_id), idempotency_key, request_hash,
            project_id=project_id,
        )
        if replay is not None:
            return replay
        timestamp = now()
        self.store.conn.execute(
            "UPDATE generation_variants SET viewed_at=COALESCE(viewed_at, ?) WHERE id=?",
            (timestamp, variant_id),
        )
        updated = self.store.conn.execute(
            "SELECT gv.* FROM generation_variants gv WHERE gv.id=?", (variant_id,)
        ).fetchone()
        return self._command_record(
            "variant.view", str(variant_id), idempotency_key,
            request_hash, self._variant_resource(updated), project_id=project_id,
        )

    @_durable_mutation
    def mark_generation_variants_viewed(self, generation_id, *, idempotency_key=None):
        """Persist first-view timestamps for every variant in a generation."""
        if not idempotency_key:
            raise InvalidRequestError("Idempotency-Key is required for state mutations")
        generation = self.store.conn.execute(
            "SELECT id, project_id FROM generations WHERE id=?", (generation_id,)
        ).fetchone()
        if not generation:
            raise NotFoundError("generation not found")
        project_id = str(generation["project_id"])
        request_hash = hashlib.sha256(canonical_json({"generation_id": str(generation_id)}).encode()).hexdigest()
        replay = self._command_replay(
            "generation.variants.view", str(generation_id), idempotency_key,
            request_hash, project_id=project_id,
        )
        if replay is not None:
            return replay
        timestamp = now()
        self.store.conn.execute(
            "UPDATE generation_variants SET viewed_at=COALESCE(viewed_at, ?) WHERE generation_id=?",
            (timestamp, generation_id),
        )
